import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def preference_pairs(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    targets = torch.tensor([[0, 1], [1, 2]])
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(targets)}
dataset = synth.Spec("simpo-preference-pairs", generator=preference_pairs, size=12, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class PreferenceModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=12)
    def forward(self, inputs):
        return {"logits": self.network(inputs).reshape(-1, 2, 2, 3)}
trainer = Trainer(PreferenceModel(), train, recipe="structured-objective", recipe_config={"loss": "simpo-loss", "loss_kwargs": {"beta": 2.0, "gamma": 0.5}, "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"batch": "targets"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
